window.__PROM_SHOULD_BOOT_MOBILE=()=>!0,window.__PROM_MOBILE_ROUTER_READY=Promise.resolve(null);try{localStorage.setItem("pm_force_mobile","1")}catch{}const mobileBootRoot=document.getElementById("mobile-root");mobileBootRoot.innerHTML='<div class="pm-mobile-startup" role="status">Loading Prometheus\u2026</div>';async function repairMobileBoot(){const briefly=promise=>Promise.race([Promise.resolve(promise),new Promise(resolve=>setTimeout(resolve,2500))]);try{const registration=await briefly(navigator.serviceWorker?.getRegistration?.(location.href));registration&&await briefly(registration.unregister())}catch{}try{const keys=await briefly(caches.keys());keys&&await briefly(Promise.all(keys.filter(key=>key.startsWith("prometheus-")).map(key=>caches.delete(key))))}catch{}const url=new URL(location.href);url.searchParams.set("pm_recover",String(Date.now())),location.replace(url.href)}setTimeout(()=>{if(mobileBootRoot.querySelector(".pm-app, .pm-mobile-boot-error"))return;let retried=!1;try{retried=Number(sessionStorage.getItem("pm_mobile_boot_repair_at")||0)>Date.now()-6e4,retried||sessionStorage.setItem("pm_mobile_boot_repair_at",String(Date.now()))}catch{}if(!retried){mobileBootRoot.innerHTML='<div class="pm-mobile-startup" role="status">Refreshing Prometheus\u2026</div>',repairMobileBoot();return}mobileBootRoot.innerHTML='<div class="pm-mobile-startup"><div>Prometheus could not finish loading.<br><button type="button" id="pm-mobile-startup-repair">Repair app cache</button></div></div>',document.getElementById("pm-mobile-startup-repair")?.addEventListener("click",repairMobileBoot)},12e3);
